const updateMaster = `-- name: UpdateMaster :one
UPDATE masters
SET bio                  = COALESCE($1, bio),
    specialization       = COALESCE($2, specialization),
    years_of_experience  = COALESCE($3, years_of_experience),
    is_accepting_bookings = COALESCE($4, is_accepting_bookings),
    updated_at = NOW()
WHERE id = $5
RETURNING id, user_id, slug, bio, specialization, years_of_experience,
          is_accepting_bookings, default_location_id, min_price, avg_rating, reviews_count,
          created_at, updated_at
`

