const updateMasterRating = `-- name: UpdateMasterRating :exec
UPDATE masters SET
    avg_rating = (SELECT COALESCE(AVG(r.rating), 0)
                  FROM reviews r
                  WHERE r.target_id = masters.id AND r.target = 1 AND r.status = 1),
    reviews_count = (SELECT COUNT(*)
                     FROM reviews r
                     WHERE r.target_id = masters.id AND r.target = 1 AND r.status = 1),
    updated_at = NOW()
WHERE masters.id = $1
`

func (q *Queries) UpdateMasterRating(ctx context.Context, id int32) error {
	_, err := q.db.Exec(ctx, updateMasterRating, id)
	return err
}

